-- Money is independent of prototype fixtures. Currency is explicitly USD.
create domain public.money_signed_cents as bigint check(value between -9007199254740991 and 9007199254740991);
create domain public.money_nonnegative_cents as bigint check(value between 0 and 9007199254740991);
create table public.money_versions(user_id uuid primary key references auth.users on delete cascade,revision bigint not null default 0);
create table public.money_commands(user_id uuid not null references auth.users on delete cascade,id uuid not null,request_hash bytea not null,revision bigint not null,primary key(user_id,id));
create table public.money_deleted_ids(user_id uuid not null references auth.users on delete cascade,collection text not null,id uuid not null,deleted_at timestamptz not null default clock_timestamp(),primary key(user_id,collection,id));
create table public.money_categories(id uuid primary key,user_id uuid not null references auth.users on delete cascade,name text not null check(length(btrim(name)) between 1 and 100),accent text not null check(accent in ('primary','secondary','pop','warm','info') or accent~'^#[0-9a-fA-F]{6}$'),icon_id text,archived boolean not null,currency text not null default 'USD' check(currency='USD'),position integer not null default 0,captured_time_zone text not null,created_at timestamptz not null default clock_timestamp(),updated_at timestamptz not null default clock_timestamp(),unique(user_id,id));
create table public.allocation_groups(id uuid primary key,user_id uuid not null references auth.users on delete cascade,name text not null check(length(btrim(name)) between 1 and 100),accent text not null check(accent in ('primary','secondary','pop','warm','info') or accent~'^#[0-9a-fA-F]{6}$'),currency text not null default 'USD' check(currency='USD'),position integer not null default 0,captured_time_zone text not null,created_at timestamptz not null default clock_timestamp(),updated_at timestamptz not null default clock_timestamp(),unique(user_id,id));
create table public.money_tags(id uuid primary key,user_id uuid not null references auth.users on delete cascade,name text not null check(length(btrim(name)) between 1 and 100),archived boolean not null,currency text not null default 'USD' check(currency='USD'),position integer not null default 0,captured_time_zone text not null,created_at timestamptz not null default clock_timestamp(),updated_at timestamptz not null default clock_timestamp(),unique(user_id,id));
create table public.payment_methods(id uuid primary key,user_id uuid not null references auth.users on delete cascade,name text not null check(length(btrim(name)) between 1 and 100),currency text not null default 'USD' check(currency='USD'),position integer not null default 0,captured_time_zone text not null,created_at timestamptz not null default clock_timestamp(),updated_at timestamptz not null default clock_timestamp(),unique(user_id,id));
create table public.cards(id uuid primary key,user_id uuid not null references auth.users on delete cascade,name text not null check(length(btrim(name)) between 1 and 100),opening_balance_cents public.money_signed_cents not null,opening_as_of date not null,limit_cents public.money_nonnegative_cents,apr numeric check(apr>=0 and apr<=1000000),due_date date,minimum_cents public.money_nonnegative_cents,planned_payment_cents public.money_nonnegative_cents,note text check(length(note)<=4000),currency text not null default 'USD' check(currency='USD'),position integer not null default 0,captured_time_zone text not null,created_at timestamptz not null default clock_timestamp(),updated_at timestamptz not null default clock_timestamp(),unique(user_id,id));
create table public.recurring_commitments(id uuid primary key,user_id uuid not null references auth.users on delete cascade,name text not null check(length(btrim(name)) between 1 and 160),amount_cents public.money_nonnegative_cents,amount_behavior text not null check(amount_behavior in ('fixed','estimated')),category_id uuid,anchor_date date not null,billing_source text not null check(length(btrim(billing_source)) between 1 and 160),card_id uuid,payment_method_id uuid,status text not null check(status in ('active','paused','cancelled')),note text check(length(note)<=4000),manage_at text check(length(manage_at)<=2048 and manage_at ~* '^https?://[^[:space:][:cntrl:]]+$'),cancelled_date date,end_date date,interval_count bigint not null check(interval_count between 1 and 9007199254740991),interval_unit text not null check(interval_unit in ('day','week','month','year')),currency text not null default 'USD' check(currency='USD'),position integer not null default 0,captured_time_zone text not null,created_at timestamptz not null default clock_timestamp(),updated_at timestamptz not null default clock_timestamp(),unique(user_id,id));
create table public.bills(id uuid primary key,user_id uuid not null references auth.users on delete cascade,name text not null check(length(btrim(name)) between 1 and 160),amount_cents public.money_nonnegative_cents not null,due_date date not null,recurrence text not null check(recurrence in ('once','weekly','monthly','yearly')),category_id uuid,card_id uuid,paid boolean not null,note text check(length(note)<=4000),recurring_id uuid,currency text not null default 'USD' check(currency='USD'),position integer not null default 0,captured_time_zone text not null,created_at timestamptz not null default clock_timestamp(),updated_at timestamptz not null default clock_timestamp(),unique(user_id,id));
create table public.paycheck_templates(id uuid primary key,user_id uuid not null references auth.users on delete cascade,name text not null check(length(btrim(name)) between 1 and 100),expected_cents public.money_nonnegative_cents,currency text not null default 'USD' check(currency='USD'),position integer not null default 0,captured_time_zone text not null,created_at timestamptz not null default clock_timestamp(),updated_at timestamptz not null default clock_timestamp(),unique(user_id,id));
create table public.paychecks(id uuid primary key,user_id uuid not null references auth.users on delete cascade,name text not null check(length(btrim(name)) between 1 and 100),received_date date not null,period_start date not null,period_end date not null,expected_cents public.money_nonnegative_cents,actual_cents public.money_nonnegative_cents,note text check(length(note)<=4000),template_id uuid,currency text not null default 'USD' check(currency='USD'),position integer not null default 0,captured_time_zone text not null,created_at timestamptz not null default clock_timestamp(),updated_at timestamptz not null default clock_timestamp(),unique(user_id,id));
create table public.allocations(id uuid primary key,user_id uuid not null references auth.users on delete cascade,paycheck_id uuid not null,name text not null check(length(btrim(name)) between 1 and 160),planned_cents public.money_nonnegative_cents not null,allocation_group_id uuid not null,category_id uuid,subcategory_id uuid,actual_cents public.money_nonnegative_cents,due_date date,bill_id uuid,card_id uuid,note text check(length(note)<=4000),currency text not null default 'USD' check(currency='USD'),position integer not null default 0,captured_time_zone text not null,created_at timestamptz not null default clock_timestamp(),updated_at timestamptz not null default clock_timestamp(),unique(user_id,id));
create table public.transactions(id uuid primary key,user_id uuid not null references auth.users on delete cascade,merchant text not null check(length(btrim(merchant)) between 1 and 160),amount_cents public.money_nonnegative_cents not null,local_date date not null,category_id uuid,subcategory_id uuid,payment_label text not null check(length(payment_label)<=200),payment_method_id uuid,card_id uuid,note text check(length(note)<=4000),allocation_id uuid,currency text not null default 'USD' check(currency='USD'),position integer not null default 0,captured_time_zone text not null,created_at timestamptz not null default clock_timestamp(),updated_at timestamptz not null default clock_timestamp(),unique(user_id,id));
create table public.card_payments(id uuid primary key,user_id uuid not null references auth.users on delete cascade,card_id uuid not null,amount_cents public.money_nonnegative_cents not null check(amount_cents>0),local_date date not null,paycheck_id uuid,allocation_id uuid,note text check(length(note)<=4000),currency text not null default 'USD' check(currency='USD'),position integer not null default 0,captured_time_zone text not null,created_at timestamptz not null default clock_timestamp(),updated_at timestamptz not null default clock_timestamp(),unique(user_id,id));
create table public.money_subcategories(id uuid primary key,user_id uuid not null references auth.users on delete cascade,category_id uuid not null,name text not null check(length(btrim(name)) between 1 and 60),position integer not null,unique(user_id,category_id,id),foreign key(user_id,category_id) references public.money_categories(user_id,id) deferrable initially deferred);
create table public.transaction_splits(id uuid primary key,user_id uuid not null references auth.users on delete cascade,transaction_id uuid not null,category_id uuid,subcategory_id uuid,amount_cents public.money_nonnegative_cents not null,position integer not null,foreign key(user_id,transaction_id) references public.transactions(user_id,id) on delete cascade deferrable initially deferred);
create table public.transaction_tag_links(user_id uuid not null references auth.users on delete cascade,transaction_id uuid not null,tag_id uuid not null,primary key(user_id,transaction_id,tag_id),foreign key(user_id,transaction_id) references public.transactions(user_id,id) on delete cascade deferrable initially deferred,foreign key(user_id,tag_id) references public.money_tags(user_id,id) deferrable initially deferred);
create table public.paycheck_template_allocations(user_id uuid not null references auth.users on delete cascade,template_id uuid not null,position integer not null,name text not null check(length(btrim(name)) between 1 and 160),planned_cents public.money_nonnegative_cents not null,allocation_group_id uuid not null,category_id uuid,subcategory_id uuid,bill_id uuid,card_id uuid,note text check(length(note)<=4000),primary key(user_id,template_id,position),foreign key(user_id,template_id) references public.paycheck_templates(user_id,id) on delete cascade deferrable initially deferred);
-- Keep explicit revisions of recurring expectations; these never create actuals.
create table public.recurring_versions(user_id uuid not null references auth.users on delete cascade,commitment_id uuid not null,revision bigint not null,recorded_at timestamptz not null default clock_timestamp(),definition jsonb not null,primary key(user_id,commitment_id,revision),foreign key(user_id,commitment_id) references public.recurring_commitments(user_id,id) on delete cascade deferrable initially deferred);
alter table public.recurring_commitments add foreign key(user_id,category_id) references public.money_categories(user_id,id) deferrable initially deferred;
alter table public.recurring_commitments add foreign key(user_id,card_id) references public.cards(user_id,id) deferrable initially deferred;
alter table public.recurring_commitments add foreign key(user_id,payment_method_id) references public.payment_methods(user_id,id) deferrable initially deferred;
alter table public.bills add foreign key(user_id,category_id) references public.money_categories(user_id,id) deferrable initially deferred;
alter table public.bills add foreign key(user_id,card_id) references public.cards(user_id,id) deferrable initially deferred;
alter table public.bills add foreign key(user_id,recurring_id) references public.recurring_commitments(user_id,id) deferrable initially deferred;
alter table public.paychecks add foreign key(user_id,template_id) references public.paycheck_templates(user_id,id) deferrable initially deferred;
alter table public.allocations add foreign key(user_id,paycheck_id) references public.paychecks(user_id,id) deferrable initially deferred;
alter table public.allocations add foreign key(user_id,allocation_group_id) references public.allocation_groups(user_id,id) deferrable initially deferred;
alter table public.allocations add foreign key(user_id,category_id) references public.money_categories(user_id,id) deferrable initially deferred;
alter table public.allocations add foreign key(user_id,bill_id) references public.bills(user_id,id) deferrable initially deferred;
alter table public.allocations add foreign key(user_id,card_id) references public.cards(user_id,id) deferrable initially deferred;
alter table public.allocations add check(subcategory_id is null or category_id is not null), add foreign key(user_id,category_id,subcategory_id) references public.money_subcategories(user_id,category_id,id) deferrable initially deferred;
alter table public.transactions add foreign key(user_id,category_id) references public.money_categories(user_id,id) deferrable initially deferred;
alter table public.transactions add foreign key(user_id,payment_method_id) references public.payment_methods(user_id,id) deferrable initially deferred;
alter table public.transactions add foreign key(user_id,card_id) references public.cards(user_id,id) deferrable initially deferred;
alter table public.transactions add foreign key(user_id,allocation_id) references public.allocations(user_id,id) deferrable initially deferred;
alter table public.transactions add check(subcategory_id is null or category_id is not null), add foreign key(user_id,category_id,subcategory_id) references public.money_subcategories(user_id,category_id,id) deferrable initially deferred;
alter table public.card_payments add foreign key(user_id,card_id) references public.cards(user_id,id) deferrable initially deferred;
alter table public.card_payments add foreign key(user_id,paycheck_id) references public.paychecks(user_id,id) deferrable initially deferred;
alter table public.card_payments add foreign key(user_id,allocation_id) references public.allocations(user_id,id) deferrable initially deferred;
alter table public.transaction_splits add foreign key(user_id,category_id) references public.money_categories(user_id,id) deferrable initially deferred;
alter table public.transaction_splits add check(subcategory_id is null or category_id is not null), add foreign key(user_id,category_id,subcategory_id) references public.money_subcategories(user_id,category_id,id) deferrable initially deferred;
alter table public.paycheck_template_allocations add foreign key(user_id,category_id) references public.money_categories(user_id,id) deferrable initially deferred;
alter table public.paycheck_template_allocations add foreign key(user_id,allocation_group_id) references public.allocation_groups(user_id,id) deferrable initially deferred;
alter table public.paycheck_template_allocations add foreign key(user_id,bill_id) references public.bills(user_id,id) deferrable initially deferred;
alter table public.paycheck_template_allocations add foreign key(user_id,card_id) references public.cards(user_id,id) deferrable initially deferred;
alter table public.paycheck_template_allocations add check(subcategory_id is null or category_id is not null), add foreign key(user_id,category_id,subcategory_id) references public.money_subcategories(user_id,category_id,id) deferrable initially deferred;
alter table public.paychecks add check(period_start<=period_end);
alter table public.transactions add check(card_id is null or payment_method_id is null);
alter table public.recurring_commitments add check(card_id is null or payment_method_id is null);
create index money_transaction_card on public.transactions(user_id,card_id,local_date);
create index money_splits_parent on public.transaction_splits(user_id,transaction_id,position);
create index money_allocations_paycheck on public.allocations(user_id,paycheck_id,position);
create index money_transactions_period on public.transactions(user_id,local_date);
create index money_payments_card_date on public.card_payments(user_id,card_id,local_date);
create index money_paychecks_period on public.paychecks(user_id,period_start,period_end);
do $$ declare t text;begin foreach t in array array['money_categories','allocation_groups','money_tags','payment_methods','cards','recurring_commitments','bills','paycheck_templates','paychecks','allocations','transactions','card_payments','money_versions','money_commands','money_deleted_ids','money_subcategories','transaction_splits','transaction_tag_links','paycheck_template_allocations','recurring_versions'] loop execute format('alter table public.%I enable row level security',t);execute format('revoke all on public.%I from anon,authenticated',t);execute format('grant select on public.%I to authenticated',t);execute format('create policy owner_read on public.%I for select to authenticated using ((select auth.uid())=user_id)',t);end loop;end $$;
create function public.read_money() returns jsonb language plpgsql stable security invoker set search_path='' as $$ begin if auth.uid() is null then raise exception 'Sign in required' using errcode='42501';end if;return jsonb_build_object('revision',coalesce((select revision from public.money_versions where user_id=auth.uid()),0),'state',jsonb_build_object(
'categories',coalesce((select jsonb_agg(jsonb_strip_nulls(jsonb_build_object('id',m.id,'name',m.name,'accent',m.accent,'icon',m.icon_id,'archived',m.archived,'subcategories',coalesce((select jsonb_agg(jsonb_build_object('id',c.id,'name',c.name) order by c.position) from public.money_subcategories c where c.user_id=m.user_id and c.category_id=m.id),'[]'))) order by m.position,m.id) from public.money_categories m where m.user_id=auth.uid()),'[]'),
'groups',coalesce((select jsonb_agg(jsonb_strip_nulls(jsonb_build_object('id',m.id,'name',m.name,'accent',m.accent)) order by m.position,m.id) from public.allocation_groups m where m.user_id=auth.uid()),'[]'),
'tags',coalesce((select jsonb_agg(jsonb_strip_nulls(jsonb_build_object('id',m.id,'name',m.name,'archived',m.archived)) order by m.position,m.id) from public.money_tags m where m.user_id=auth.uid()),'[]'),
'paymentMethods',coalesce((select jsonb_agg(jsonb_strip_nulls(jsonb_build_object('id',m.id,'name',m.name)) order by m.position,m.id) from public.payment_methods m where m.user_id=auth.uid()),'[]'),
'cards',coalesce((select jsonb_agg(jsonb_strip_nulls(jsonb_build_object('id',m.id,'name',m.name,'openingBalanceCents',m.opening_balance_cents,'openingAsOf',m.opening_as_of,'limitCents',m.limit_cents,'apr',m.apr,'dueDate',m.due_date,'minimumCents',m.minimum_cents,'plannedPaymentCents',m.planned_payment_cents,'note',m.note,'balanceCents',(m.opening_balance_cents+coalesce((select sum(t.amount_cents) from public.transactions t where t.user_id=m.user_id and t.card_id=m.id and t.local_date>=m.opening_as_of),0)-coalesce((select sum(p.amount_cents) from public.card_payments p where p.user_id=m.user_id and p.card_id=m.id and p.local_date>=m.opening_as_of),0)))) order by m.position,m.id) from public.cards m where m.user_id=auth.uid()),'[]'),
'recurring',coalesce((select jsonb_agg(jsonb_strip_nulls(jsonb_build_object('id',m.id,'name',m.name,'amountCents',m.amount_cents,'amountBehavior',m.amount_behavior,'categoryId',m.category_id,'nextChargeDate',m.anchor_date,'billingSource',m.billing_source,'cardId',m.card_id,'paymentMethodId',m.payment_method_id,'status',m.status,'note',m.note,'manageAt',m.manage_at,'cancelledDate',m.cancelled_date,'endDate',m.end_date,'recurrence',jsonb_build_object('interval',m.interval_count,'unit',m.interval_unit))) order by m.position,m.id) from public.recurring_commitments m where m.user_id=auth.uid()),'[]'),
'bills',coalesce((select jsonb_agg(jsonb_strip_nulls(jsonb_build_object('id',m.id,'name',m.name,'amountCents',m.amount_cents,'dueDate',m.due_date,'recurrence',m.recurrence,'categoryId',m.category_id,'cardId',m.card_id,'paid',m.paid,'note',m.note,'recurringId',m.recurring_id)) order by m.position,m.id) from public.bills m where m.user_id=auth.uid()),'[]'),
'templates',coalesce((select jsonb_agg(jsonb_strip_nulls(jsonb_build_object('id',m.id,'name',m.name,'expectedCents',m.expected_cents,'allocations',coalesce((select jsonb_agg(jsonb_strip_nulls(jsonb_build_object('name',c.name,'plannedCents',c.planned_cents,'groupId',c.allocation_group_id,'categoryId',c.category_id,'subcategoryId',c.subcategory_id,'billId',c.bill_id,'cardId',c.card_id,'note',c.note)) order by c.position) from public.paycheck_template_allocations c where c.user_id=m.user_id and c.template_id=m.id),'[]'))) order by m.position,m.id) from public.paycheck_templates m where m.user_id=auth.uid()),'[]'),
'paychecks',coalesce((select jsonb_agg(jsonb_strip_nulls(jsonb_build_object('id',m.id,'name',m.name,'receivedDate',m.received_date,'periodStart',m.period_start,'periodEnd',m.period_end,'expectedCents',m.expected_cents,'actualCents',m.actual_cents,'note',m.note,'templateId',m.template_id)) order by m.position,m.id) from public.paychecks m where m.user_id=auth.uid()),'[]'),
'allocations',coalesce((select jsonb_agg(jsonb_strip_nulls(jsonb_build_object('id',m.id,'paycheckId',m.paycheck_id,'name',m.name,'plannedCents',m.planned_cents,'groupId',m.allocation_group_id,'categoryId',m.category_id,'subcategoryId',m.subcategory_id,'actualCents',m.actual_cents,'dueDate',m.due_date,'billId',m.bill_id,'cardId',m.card_id,'note',m.note)) order by m.position,m.id) from public.allocations m where m.user_id=auth.uid()),'[]'),
'transactions',coalesce((select jsonb_agg(jsonb_strip_nulls(jsonb_build_object('id',m.id,'merchant',m.merchant,'amountCents',m.amount_cents,'date',m.local_date,'categoryId',m.category_id,'subcategoryId',m.subcategory_id,'paymentMethod',m.payment_label,'paymentMethodId',m.payment_method_id,'cardId',m.card_id,'note',m.note,'allocationId',m.allocation_id,'splits',coalesce((select jsonb_agg(jsonb_strip_nulls(jsonb_build_object('id',c.id,'categoryId',c.category_id,'subcategoryId',c.subcategory_id,'amountCents',c.amount_cents)) order by c.position) from public.transaction_splits c where c.user_id=m.user_id and c.transaction_id=m.id),'[]'),'tagIds',coalesce((select jsonb_agg(tag_id order by tag_id) from public.transaction_tag_links c where c.user_id=m.user_id and c.transaction_id=m.id),'[]'))) order by m.position,m.id) from public.transactions m where m.user_id=auth.uid()),'[]'),
'payments',coalesce((select jsonb_agg(jsonb_strip_nulls(jsonb_build_object('id',m.id,'cardId',m.card_id,'amountCents',m.amount_cents,'date',m.local_date,'paycheckId',m.paycheck_id,'allocationId',m.allocation_id,'note',m.note)) order by m.position,m.id) from public.card_payments m where m.user_id=auth.uid()),'[]')
));end $$;revoke all on function public.read_money() from public,anon;grant execute on function public.read_money() to authenticated;
create function public.save_money(p_expected_revision bigint,p_command_id uuid,p_state jsonb) returns bigint language plpgsql security definer set search_path='' as $$
declare uid uuid:=auth.uid();v bigint;receipt public.money_commands;h bytea;item jsonb;child jsonb;k text;z text;pos integer;subpos integer;old_definition jsonb;
begin
 if uid is null then raise exception 'Sign in required' using errcode='42501';end if;
 select time_zone into z from public.profiles where id=uid;if z is null or not exists(select 1 from pg_catalog.pg_timezone_names where name=z) then raise exception 'Configure a valid profile timezone' using errcode='22023';end if;
 if p_expected_revision is null or p_command_id is null or jsonb_typeof(p_state) is distinct from 'object' or octet_length(p_state::text)>8388608 then raise exception 'Invalid Money library' using errcode='22023';end if;
 foreach k in array array['categories','groups','tags','paymentMethods','cards','recurring','bills','templates','paychecks','allocations','transactions','payments'] loop if jsonb_typeof(p_state->k) is distinct from 'array' or jsonb_array_length(p_state->k)>5000 or (select count(distinct (value->>'id')::uuid) from jsonb_array_elements(p_state->k))<>jsonb_array_length(p_state->k) then raise exception 'Invalid, duplicate or oversized Money collection' using errcode='22023';end if;end loop;
 insert into public.money_versions(user_id) values(uid) on conflict do nothing;select revision into v from public.money_versions where user_id=uid for update;
 h:=sha256(convert_to(p_state::text,'UTF8'));select * into receipt from public.money_commands where user_id=uid and id=p_command_id;if found then if receipt.request_hash<>h then raise exception 'Command reused' using errcode='22023';end if;return receipt.revision;end if;
 if v<>p_expected_revision then raise exception 'Money changed; reload before saving' using errcode='40001';end if;
 if exists(select 1 from public.money_categories where user_id=uid and id not in(select (value->>'id')::uuid from jsonb_array_elements(p_state->'categories'))) then
 raise exception 'Preserve existing Money definitions; use the supported archive/status actions' using errcode='22023';
 end if;
 pos:=0;for item in select value from jsonb_array_elements(p_state->'categories') loop
 if exists(select 1 from public.money_categories where id=(item->>'id')::uuid and user_id<>uid) then raise exception 'Record unavailable' using errcode='42501';end if;
 if exists(select 1 from public.money_deleted_ids where user_id=uid and collection='categories' and id=(item->>'id')::uuid) then raise exception 'Deleted Money record cannot be recreated' using errcode='22023';end if;
 insert into public.money_categories(id,user_id,captured_time_zone,position,name,accent,icon_id,archived) select r.id,r.user_id,r.captured_time_zone,r.position,r.name,r.accent,r.icon_id,r.archived from jsonb_populate_record(null::public.money_categories,jsonb_build_object('id',item->'id','user_id',to_jsonb(uid),'captured_time_zone',to_jsonb(z),'position',to_jsonb(pos),'name',item#>'{name}','accent',item#>'{accent}','icon_id',item#>'{icon}','archived',item#>'{archived}')) r on conflict(id) do update set position=excluded.position,name=excluded.name,accent=excluded.accent,icon_id=excluded.icon_id,archived=excluded.archived,updated_at=clock_timestamp() where public.money_categories.user_id=uid and (public.money_categories.position,public.money_categories.name,public.money_categories.accent,public.money_categories.icon_id,public.money_categories.archived) is distinct from (excluded.position,excluded.name,excluded.accent,excluded.icon_id,excluded.archived);
 delete from public.money_subcategories where user_id=uid and category_id=(item->>'id')::uuid and id not in(select (value->>'id')::uuid from jsonb_array_elements(item->'subcategories'));
