 insert into public.transactions(id,user_id,captured_time_zone,position,merchant,amount_cents,local_date,category_id,subcategory_id,payment_label,payment_method_id,card_id,note,allocation_id) select r.id,r.user_id,r.captured_time_zone,r.position,r.merchant,r.amount_cents,r.local_date,r.category_id,r.subcategory_id,r.payment_label,r.payment_method_id,r.card_id,r.note,r.allocation_id from jsonb_populate_record(null::public.transactions,jsonb_build_object('id',item->'id','user_id',to_jsonb(uid),'captured_time_zone',to_jsonb(z),'position',to_jsonb(pos),'merchant',item#>'{merchant}','amount_cents',item#>'{amountCents}','local_date',item#>'{date}','category_id',item#>'{categoryId}','subcategory_id',item#>'{subcategoryId}','payment_label',item#>'{paymentMethod}','payment_method_id',item#>'{paymentMethodId}','card_id',item#>'{cardId}','note',item#>'{note}','allocation_id',item#>'{allocationId}')) r on conflict(id) do update set position=excluded.position,merchant=excluded.merchant,amount_cents=excluded.amount_cents,local_date=excluded.local_date,category_id=excluded.category_id,subcategory_id=excluded.subcategory_id,payment_label=excluded.payment_label,payment_method_id=excluded.payment_method_id,card_id=excluded.card_id,note=excluded.note,allocation_id=excluded.allocation_id,updated_at=clock_timestamp() where public.transactions.user_id=uid and (public.transactions.position,public.transactions.merchant,public.transactions.amount_cents,public.transactions.local_date,public.transactions.category_id,public.transactions.subcategory_id,public.transactions.payment_label,public.transactions.payment_method_id,public.transactions.card_id,public.transactions.note,public.transactions.allocation_id) is distinct from (excluded.position,excluded.merchant,excluded.amount_cents,excluded.local_date,excluded.category_id,excluded.subcategory_id,excluded.payment_label,excluded.payment_method_id,excluded.card_id,excluded.note,excluded.allocation_id);
 if jsonb_typeof(item->'splits') is distinct from 'array' or jsonb_typeof(item->'tagIds') is distinct from 'array' then raise exception 'Invalid transaction detail' using errcode='22023';end if;
 delete from public.transaction_splits where user_id=uid and transaction_id=(item->>'id')::uuid;
 subpos:=0;for child in select value from jsonb_array_elements(item->'splits') loop
 if exists(select 1 from public.transaction_splits where id=(child->>'id')::uuid and (user_id<>uid or transaction_id<>(item->>'id')::uuid)) then raise exception 'Split unavailable' using errcode='42501';end if;
 insert into public.transaction_splits values((child->>'id')::uuid,uid,(item->>'id')::uuid,(child->>'categoryId')::uuid,(child->>'subcategoryId')::uuid,(child->>'amountCents')::bigint,subpos);subpos:=subpos+1;end loop;
 delete from public.transaction_tag_links where user_id=uid and transaction_id=(item->>'id')::uuid;
 for child in select value from jsonb_array_elements(item->'tagIds') loop insert into public.transaction_tag_links values(uid,(item->>'id')::uuid,(child#>>'{}')::uuid);end loop;
 pos:=pos+1;end loop;
 if exists(select 1 from public.card_payments where user_id=uid and id not in(select (value->>'id')::uuid from jsonb_array_elements(p_state->'payments'))) then
 insert into public.money_deleted_ids(user_id,collection,id) select uid,'payments',id from public.card_payments where user_id=uid and id not in(select (value->>'id')::uuid from jsonb_array_elements(p_state->'payments')) on conflict do nothing;delete from public.card_payments where user_id=uid and id not in(select (value->>'id')::uuid from jsonb_array_elements(p_state->'payments'));
 end if;
 pos:=0;for item in select value from jsonb_array_elements(p_state->'payments') loop
 if exists(select 1 from public.card_payments where id=(item->>'id')::uuid and user_id<>uid) then raise exception 'Record unavailable' using errcode='42501';end if;
 if exists(select 1 from public.money_deleted_ids where user_id=uid and collection='payments' and id=(item->>'id')::uuid) then raise exception 'Deleted Money record cannot be recreated' using errcode='22023';end if;
 if item?'date' and item->>'date' is not null and item->>'date' !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' then raise exception 'Use explicit local calendar dates' using errcode='22023';end if;
 insert into public.card_payments(id,user_id,captured_time_zone,position,card_id,amount_cents,local_date,paycheck_id,allocation_id,note) select r.id,r.user_id,r.captured_time_zone,r.position,r.card_id,r.amount_cents,r.local_date,r.paycheck_id,r.allocation_id,r.note from jsonb_populate_record(null::public.card_payments,jsonb_build_object('id',item->'id','user_id',to_jsonb(uid),'captured_time_zone',to_jsonb(z),'position',to_jsonb(pos),'card_id',item#>'{cardId}','amount_cents',item#>'{amountCents}','local_date',item#>'{date}','paycheck_id',item#>'{paycheckId}','allocation_id',item#>'{allocationId}','note',item#>'{note}')) r on conflict(id) do update set position=excluded.position,card_id=excluded.card_id,amount_cents=excluded.amount_cents,local_date=excluded.local_date,paycheck_id=excluded.paycheck_id,allocation_id=excluded.allocation_id,note=excluded.note,updated_at=clock_timestamp() where public.card_payments.user_id=uid and (public.card_payments.position,public.card_payments.card_id,public.card_payments.amount_cents,public.card_payments.local_date,public.card_payments.paycheck_id,public.card_payments.allocation_id,public.card_payments.note) is distinct from (excluded.position,excluded.card_id,excluded.amount_cents,excluded.local_date,excluded.paycheck_id,excluded.allocation_id,excluded.note);
 pos:=pos+1;end loop;
 if exists(select 1 from public.transactions t where user_id=uid and ((select coalesce(sum(amount_cents),0) from public.transaction_splits s where s.user_id=uid and s.transaction_id=t.id)>t.amount_cents or (t.allocation_id is not null and exists(select 1 from public.allocations a where a.id=t.allocation_id and a.user_id=uid and a.card_id is not null)))) then raise exception 'Invalid spending split or card-payment allocation' using errcode='22023';end if;
 if exists(select 1 from public.card_payments p join public.allocations a on a.id=p.allocation_id and a.user_id=p.user_id where p.user_id=uid and (a.card_id is distinct from p.card_id or (p.paycheck_id is not null and p.paycheck_id<>a.paycheck_id))) then raise exception 'Payment allocation must match card/paycheck' using errcode='22023';end if;
 -- All partial client sums are safe, not only a potentially cancelling final sum.
 if (select coalesce(sum(amount_cents),0) from public.transactions where user_id=uid)>9007199254740991 or (select coalesce(sum(amount_cents),0) from public.card_payments where user_id=uid)>9007199254740991 or (select coalesce(sum(planned_cents),0) from public.allocations where user_id=uid)>9007199254740991 or (select coalesce(sum(coalesce(expected_cents,0)),0)+coalesce(sum(coalesce(actual_cents,0)),0) from public.paychecks where user_id=uid)>9007199254740991 then raise exception 'Money totals exceed supported exact precision' using errcode='22023';end if;
 if exists(select 1 from public.cards c where user_id=uid and abs(opening_balance_cents::numeric)+coalesce((select sum(t.amount_cents) from public.transactions t where t.user_id=uid and t.card_id=c.id and t.local_date>=c.opening_as_of),0)+coalesce((select sum(p.amount_cents) from public.card_payments p where p.user_id=uid and p.card_id=c.id and p.local_date>=c.opening_as_of),0)>9007199254740991) then raise exception 'Card reconciliation exceeds supported exact precision' using errcode='22023';end if;
 if (select coalesce(sum(amount_cents*case interval_unit when 'day' then 365.2425 when 'week' then 52 when 'month' then 12 else 1 end/interval_count),0) from public.recurring_commitments where user_id=uid)>9007199254740991 then raise exception 'Recurring estimates exceed supported precision' using errcode='22023';end if;
 update public.money_versions set revision=revision+1 where user_id=uid returning revision into v;insert into public.money_commands values(uid,p_command_id,h,v);return v;
end $$;revoke all on function public.save_money(bigint,uuid,jsonb) from public,anon;grant execute on function public.save_money(bigint,uuid,jsonb) to authenticated;

create or replace function public.export_personal_data() returns jsonb language plpgsql stable security invoker set search_path='' as $$
declare uid uuid:=auth.uid();
begin
 if uid is null then raise exception 'Sign in required' using errcode='42501';end if;
 return jsonb_build_object('schema_version',2,'exported_at',current_timestamp,'profile',(select to_jsonb(p) from public.profiles p where id=uid),
 'daily_records',(select coalesce(jsonb_agg(to_jsonb(r)),'[]'::jsonb) from public.daily_records r where user_id=uid),
 'daily_priorities',(select coalesce(jsonb_agg(to_jsonb(r)),'[]'::jsonb) from public.daily_priorities r where user_id=uid),
 'mood_checkins',(select coalesce(jsonb_agg(to_jsonb(r)),'[]'::jsonb) from public.mood_checkins r where user_id=uid),
 'checkin_emotions',(select coalesce(jsonb_agg(to_jsonb(r)),'[]'::jsonb) from public.checkin_emotions r where user_id=uid),
 'checkin_influences',(select coalesce(jsonb_agg(to_jsonb(r)),'[]'::jsonb) from public.checkin_influences r where user_id=uid),
 'influence_tags',(select coalesce(jsonb_agg(to_jsonb(r)),'[]'::jsonb) from public.influence_tags r where user_id=uid),
 'emotion_favorites',(select coalesce(jsonb_agg(to_jsonb(r)),'[]'::jsonb) from public.emotion_favorites r where user_id=uid),
 'workspaces',(select coalesce(jsonb_agg(to_jsonb(r)),'[]'::jsonb) from public.workspaces r where user_id=uid),
 'task_groups',(select coalesce(jsonb_agg(to_jsonb(r)),'[]'::jsonb) from public.task_groups r where user_id=uid),
 'task_tags',(select coalesce(jsonb_agg(to_jsonb(r)),'[]'::jsonb) from public.task_tags r where user_id=uid),
 'tasks',(select coalesce(jsonb_agg(to_jsonb(r)),'[]'::jsonb) from public.tasks r where user_id=uid),
 'task_subtasks',(select coalesce(jsonb_agg(to_jsonb(r)),'[]'::jsonb) from public.task_subtasks r where user_id=uid),
 'task_tag_links',(select coalesce(jsonb_agg(to_jsonb(r)),'[]'::jsonb) from public.task_tag_links r where user_id=uid),
 'planner_events',(select coalesce(jsonb_agg(to_jsonb(r)),'[]'::jsonb) from public.planner_events r where user_id=uid),
 'task_time_sessions',(select coalesce(jsonb_agg(to_jsonb(r)),'[]'::jsonb) from public.task_time_sessions r where user_id=uid),
 'task_completion_events',(select coalesce(jsonb_agg(to_jsonb(r)),'[]'::jsonb) from public.task_completion_events r where user_id=uid),
 'notes',(select coalesce(jsonb_agg(to_jsonb(r)-'search_vector'),'[]'::jsonb) from public.notes r where user_id=uid),
 'note_tags',(select coalesce(jsonb_agg(to_jsonb(r)),'[]'::jsonb) from public.note_tags r where user_id=uid),
 'note_tag_links',(select coalesce(jsonb_agg(to_jsonb(r)),'[]'::jsonb) from public.note_tag_links r where user_id=uid),
 'wellness',public.read_wellness()->'state','rituals',public.read_rituals()->'state','money',public.read_money()->'state','money_recurring_versions',(select coalesce(jsonb_agg(to_jsonb(r)),'[]'::jsonb) from public.recurring_versions r where user_id=uid),
 'emotion_catalog',(select jsonb_agg(to_jsonb(e)) from public.emotion_catalog e));
end $$;
